function hexToVec4(hex) {
  const r = parseInt(hex.slice(1, 3), 16) / 255;
  const g = parseInt(hex.slice(3, 5), 16) / 255;
  const b = parseInt(hex.slice(5, 7), 16) / 255;
  return [r, g, b, 1.0];
}



const params = {
  horizon: 0.3, // should vary with scroll
  scale: 0.5,
  distortionScale: 80.0,
  distortion: 0.01,
  sky1: hexToVec4("#010F0C"),
  sky2: hexToVec4("#3C3EA1"),
  cloud1: hexToVec4("#ff0000"),
  cloud2: hexToVec4("#efeab7"),
};

// Parameter entries (preset so user does not have control)
document.getElementById("horizon")?.addEventListener("input", e => params.horizon = parseFloat(e.target.value));
document.getElementById("scale")?.addEventListener("input", e => params.scale = parseFloat(e.target.value));
document.getElementById("distortionScale")?.addEventListener("input", e => params.distortionScale = parseFloat(e.target.value));
document.getElementById("distortion")?.addEventListener("input", e => params.distortion = parseFloat(e.target.value));
document.getElementById("sky1")?.addEventListener("input", e => params.sky1 = hexToVec4(e.target.value));
document.getElementById("sky2")?.addEventListener("input", e => params.sky2 = hexToVec4(e.target.value));
document.getElementById("cloud1")?.addEventListener("input", e => params.cloud1 = hexToVec4(e.target.value));
document.getElementById("cloud2")?.addEventListener("input", e => params.cloud2 = hexToVec4(e.target.value));

// File input system (also optional — preset texture load is below)
document.getElementById("cloudTexInput")?.addEventListener("change", (e) => {
  const file = e.target.files[0];
  if (!file) return;
  const url = URL.createObjectURL(file);
  const image = new Image();
  image.onload = () => { loadTextureFromImage(image); URL.revokeObjectURL(url); };
  image.src = url;
});

// Horizon moves with scroll
function updateHorizonFromScroll() {
  const maxScroll = document.documentElement.scrollHeight - window.innerHeight;
  const fraction = maxScroll > 0 ? window.scrollY / maxScroll : 0;
  const t = Math.min(Math.max(fraction, 0), 1.0);
  const lerp = (start, end, t) => (1 - t) * start + t * end;
  params.horizon = lerp(0.5, 1.5, t); // lerp between min and max values
}
window.addEventListener("scroll", updateHorizonFromScroll);
updateHorizonFromScroll(); // sets start


let _loadTextureFromImageRef = null;
function loadTextureFromImage(image) {
  if (_loadTextureFromImageRef) _loadTextureFromImageRef(image);
}

const cloudImage = new Image();
cloudImage.onload = () => loadTextureFromImage(cloudImage);
cloudImage.onerror = () => console.error("Could not load cloud texture — check the path/case");
cloudImage.src = "/images/cloud.jpg";

function main() {
  const canvas = document.querySelector("#gl-canvas");
  const gl = canvas.getContext("webgl");
  if (gl === null) {
    alert("Unable to initialize WebGL. Your browser or machine may not support it.");
    return;
  }

  function resize() {
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = window.innerWidth * dpr;
    canvas.height = window.innerHeight * dpr;
    gl.viewport(0, 0, canvas.width, canvas.height);
  }
  window.addEventListener("resize", resize);
  resize();

  //Passes only screen coords
  const vsSource = `
    attribute vec2 position;
    varying vec2 vUv;
    void main() {
      vUv = position * 0.5 + 0.5; // map clip space [-1,1] to uv [0,1]
      gl_Position = vec4(position, 0.0, 1.0);
    }
  `;

  // Frag shader
  const fsSource = `
    precision highp float;
    varying vec2 vUv;

    uniform vec2 u_resolution;
    uniform float u_time;

    uniform vec4 u_skyColor1;
    uniform vec4 u_skyColor2;
    uniform vec4 u_cloudColor1;
    uniform vec4 u_cloudColor2;

    uniform float u_scalingFactor;
    uniform float u_horizon;
    uniform float u_distortionStrength;
    uniform float u_distortionScale;

    uniform sampler2D u_cloudTex;

    // From Unity's built-in _Time.x (t/20) and _Time.y (t)
    float timeX() { return u_time * 0.05; }
    float timeY() { return u_time; }

    float quantize(float value, float factor) {
      return floor(value * factor) / factor;
    }

    vec4 lerpColor(float value, vec4 color1, vec4 color2) {
      if (value <= 0.0) return color1;
      if (value >= 1.0) return color2;
      return mix(color1, color2, value);
    }

    float adjustSingleContrast(float channelValue, float contrast) {
      return (channelValue - 0.5) * contrast + 0.5;
    }

    vec2 hash22(vec2 p) {
      p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
      return fract(sin(p) * 43758.5453);
    }

    vec2 valueNoise2D(vec2 uv) {
      vec2 i = floor(uv);
      vec2 f = fract(uv);
      vec2 u = f * f * (3.0 - 2.0 * f);

      vec2 a = hash22(i + vec2(0.0, 0.0));
      vec2 b = hash22(i + vec2(1.0, 0.0));
      vec2 c = hash22(i + vec2(0.0, 1.0));
      vec2 d = hash22(i + vec2(1.0, 1.0));

      return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
    }

    void main() {
      vec2 uv = vUv;

      vec2 distortionOffset = (valueNoise2D(uv * u_distortionScale + timeX()) - 0.5) * u_distortionStrength;

      float skyValue = uv.y + distortionOffset.x + (0.5 - u_horizon);
      skyValue = quantize(skyValue, 16.0);
      vec4 skyColor = lerpColor(skyValue, u_skyColor1, u_skyColor2);

      float dist = abs(uv.y - u_horizon);

      vec2 scaledUV = (uv + distortionOffset) * u_scalingFactor;

      float newUVX = scaledUV.x / dist - (0.5 * u_scalingFactor) / dist + timeY() * -0.005;
      float newUVY = scaledUV.y / dist + timeY() * -0.05;
      vec2 sampleUV = vec2(newUVX, newUVY);

      
      float sampleR = texture2D(u_cloudTex, sampleUV).r;

      float aboveHorizon = uv.y > u_horizon ? 1.0 : 0.0;
      float cloudValue = clamp((0.9 - sampleR) * aboveHorizon * dist * 2.0, 0.0, 1.0);
      cloudValue = quantize(cloudValue, 16.0);

      vec4 cloudColor = lerpColor(cloudValue, u_cloudColor1, u_cloudColor2);

      gl_FragColor = mix(skyColor, cloudColor, clamp(adjustSingleContrast(cloudValue * 2.0, 1.3), 0.0, 1.0));
    }
  `;

  function compileShader(type, src) {
    const shader = gl.createShader(type);
    gl.shaderSource(shader, src);
    gl.compileShader(shader);
    if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
      console.error(gl.getShaderInfoLog(shader));
    }
    return shader;
  }

  const program = gl.createProgram();
  gl.attachShader(program, compileShader(gl.VERTEX_SHADER, vsSource));
  gl.attachShader(program, compileShader(gl.FRAGMENT_SHADER, fsSource));
  gl.linkProgram(program);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    console.error(gl.getProgramInfoLog(program));
  }
  gl.useProgram(program);

  const buffer = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([
    -1, -1,
     3, -1,
    -1,  3
  ]), gl.STATIC_DRAW);

  const posLoc = gl.getAttribLocation(program, "position");
  gl.enableVertexAttribArray(posLoc);
  gl.vertexAttribPointer(posLoc, 2, gl.FLOAT, false, 0, 0);

  const uniforms = {};
  ["u_resolution", "u_time", "u_skyColor1", "u_skyColor2",
   "u_cloudColor1", "u_cloudColor2", "u_scalingFactor", "u_horizon",
   "u_distortionStrength", "u_distortionScale", "u_cloudTex"].forEach(name => {
    uniforms[name] = gl.getUniformLocation(program, name);
  });

  //set image to power of 2 because webgl is annoying
  function isPowerOf2(value) {
    return (value & (value - 1)) === 0;
  }

  function nearestPowerOf2(value) {
    return Math.pow(2, Math.round(Math.log2(value)));
  }

  
  function toPowerOf2Canvas(image) {
    const w = nearestPowerOf2(image.width);
    const h = nearestPowerOf2(image.height);
    const c = document.createElement("canvas");
    c.width = w;
    c.height = h;
    const ctx = c.getContext("2d");
    ctx.drawImage(image, 0, 0, w, h); // stretch cloud image  to fit webgl constraints 
    return c;
  }

  const cloudTexture = gl.createTexture();
  gl.bindTexture(gl.TEXTURE_2D, cloudTexture);
  // 1x1 mid-gray placeholder so the shader has something valid to sample
  // before an image is chosen.
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, 1, 1, 0, gl.RGBA, gl.UNSIGNED_BYTE,
    new Uint8Array([128, 128, 128, 255]));
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.MIRRORED_REPEAT);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.MIRRORED_REPEAT);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);

  function loadTextureFromImageImpl(image) {
    let source = image;
    if (!isPowerOf2(image.width) || !isPowerOf2(image.height)) {
      console.warn(
        `Image is ${image.width}x${image.height}, not power-of-two. ` +
        `Redrawing onto a ${nearestPowerOf2(image.width)}x${nearestPowerOf2(image.height)} ` +
        `canvas so REPEAT wrapping still works.`
      );
      source = toPowerOf2Canvas(image);
    }

    gl.bindTexture(gl.TEXTURE_2D, cloudTexture);
    gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true); 
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, source);

    // image is mirrored to hide strong seems
    gl.generateMipmap(gl.TEXTURE_2D);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.MIRRORED_REPEAT);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.MIRRORED_REPEAT);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_LINEAR);
  }


  _loadTextureFromImageRef = loadTextureFromImageImpl;
  if (cloudImage.complete && cloudImage.naturalWidth > 0) {
    loadTextureFromImageImpl(cloudImage);
  }

  const start = performance.now();
  function render() {
    const time = (performance.now() - start) / 1000;

    gl.uniform2f(uniforms.u_resolution, canvas.width, canvas.height);
    gl.uniform1f(uniforms.u_time, time);
    gl.uniform4fv(uniforms.u_skyColor1, params.sky1);
    gl.uniform4fv(uniforms.u_skyColor2, params.sky2);
    gl.uniform4fv(uniforms.u_cloudColor1, params.cloud1);
    gl.uniform4fv(uniforms.u_cloudColor2, params.cloud2);
    gl.uniform1f(uniforms.u_scalingFactor, params.scale);
    gl.uniform1f(uniforms.u_horizon, params.horizon);
    gl.uniform1f(uniforms.u_distortionStrength, params.distortion);
    gl.uniform1f(uniforms.u_distortionScale, params.distortionScale);

    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, cloudTexture);
    gl.uniform1i(uniforms.u_cloudTex, 0);

    gl.drawArrays(gl.TRIANGLES, 0, 3);
    requestAnimationFrame(render);
  }
  requestAnimationFrame(render);
}

main();